import json

plan = json.loads("""
{"resource_changes": [
  {"address": "aws_s3_bucket_public_access_block.logs",
   "type": "aws_s3_bucket_public_access_block",
   "change": {"after": {"block_public_acls": true, "restrict_public_buckets": false}}},
  {"address": "aws_instance.api",
   "type": "aws_instance",
   "change": {"after": {"metadata_options": [{"http_tokens": "optional"}]}}},
  {"address": "aws_security_group_rule.ssh",
   "type": "aws_security_group_rule",
   "change": {"after": {"type": "ingress", "from_port": 22, "to_port": 22,
                        "cidr_blocks": ["0.0.0.0/0"]}}}
]}
""")

def check(rc):
    t, a = rc["type"], rc["change"]["after"]
    if t == "aws_s3_bucket_public_access_block":
        off = [k for k, v in a.items() if v is False]
        if off:
            return f"S3 공개 차단 꺼짐: {off}"
    if t == "aws_instance":
        if a.get("metadata_options", [{}])[0].get("http_tokens") != "required":
            return "IMDSv2 강제 안 됨(http_tokens != required)"
    if t == "aws_security_group_rule" and a.get("type") == "ingress":
        if "0.0.0.0/0" in a.get("cidr_blocks", []) and a["from_port"] <= 22 <= a["to_port"]:
            return "SSH(22)가 인터넷 전체에 열림"
    return None

fails = [(rc["address"], msg) for rc in plan["resource_changes"] if (msg := check(rc))]
for addr, msg in fails:
    print(f"FAIL {addr}: {msg}")
print(f"{len(fails)}건 위반 → 배포 중단" if fails else "통과")

# FAIL aws_s3_bucket_public_access_block.logs: S3 공개 차단 꺼짐: ['restrict_public_buckets']
# FAIL aws_instance.api: IMDSv2 강제 안 됨(http_tokens != required)
# FAIL aws_security_group_rule.ssh: SSH(22)가 인터넷 전체에 열림
# 3건 위반 → 배포 중단
